   "page": 7,
   "horizon": "FY27",
   "quantitative": false
  },
  {
   "metric": "margin",
   "statement": "We expect continued improvement in opex to NTI of 25 to 40 basis points.",
   "quote": "On opex to NTI, we expect to see continued improvement of 25 to 40 basis points from current levels.",
   "page": 7,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "other",
   "statement": "We are confident of adding 15 to 17 million new customers in FY27.",
   "quote": "In terms of customer franchise, we continue to be confident of adding 15 - 17 million new customers in FY27.",
   "page": 7,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "profit",
   "statement": "We continue to guide for ROA of 4.4% to 4.6% in FY27.",
